#include <Arduino.h>
#include <Wire.h>

static const uint8_t OLED_ADDR = 0x3C;
static uint8_t frameCounter = 0;

void oledCommand(uint8_t cmd) {
  Wire.beginTransmission(OLED_ADDR);
  Wire.write(0x00);
  Wire.write(cmd);
  const int err = Wire.endTransmission();
  Serial1.print("OLED_I2C=");
  Serial1.println(err);
}

void oledDataBurst(uint8_t valueA, uint8_t valueB) {
  Wire.beginTransmission(OLED_ADDR);
  Wire.write(0x40);
  Wire.write(valueA);
  Wire.write(valueB);
  const int err = Wire.endTransmission();
  Serial1.print("OLED_DATA=");
  Serial1.println(err);
}

void setup() {
  Serial1.setTX(0);
  Serial1.setRX(1);
  Serial1.begin(115200);
  Wire.setSDA(4);
  Wire.setSCL(5);
  Wire.begin();
  delay(20);
  Serial1.println("OLED_BOOT");
  oledCommand(0xAE);
  oledCommand(0x20);
  oledCommand(0x00);
  oledCommand(0xAF);
}

void loop() {
  const uint8_t pattern = (frameCounter & 0x01u) ? 0xAA : 0x55;
  oledDataBurst(pattern, (uint8_t)~pattern);
  Serial1.print("OLED_FRAME ");
  Serial1.println(frameCounter);
  frameCounter++;
  delay(60);
}

